import {money,norm,escapeHTML as esc,findProducts,itemKey,addItem,subtotal,sortProducts} from './core.mjs';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const read=(k,d)=>{try{return JSON.parse(localStorage.getItem('gocase-study:'+k))??d}catch{return d}};
const save=(k,v)=>{try{localStorage.setItem('gocase-study:'+k,JSON.stringify(v))}catch{}};
let cart=read('cart',[]),favorites=read('favorites',[]),catalog=[],assetMap={},product=null,currentOption=null,currentDevice=null,page=1,visibleProducts=[];
const path=decodeURI(location.pathname).replace(/\/$/,'')||'/';
const main=$('#r-main');
const asset=url=>assetMap[url]||url;
const toast=message=>{const el=$('#r-toast');el.textContent=message;el.classList.add('r-visible');clearTimeout(el.timer);el.timer=setTimeout(()=>el.classList.remove('r-visible'),4000)};
const persistCart=()=>{save('cart',cart);updateCount()};
function updateCount(){$$('.new-home-header__cart').forEach(el=>{let count=$('.r-count',el);if(!count){count=document.createElement('span');count.className='r-count';el.append(count)}count.textContent=cart.reduce((s,x)=>s+x.qty,0);count.hidden=!cart.length})}
const catButton=(label,href)=>`<a class="r-pill" href="${href}">${label}</a>`;
function card(p){return `<article class="r-card" data-slug="${esc(p.slug)}"><div class="r-card-media"><a href="/${esc(p.slug)}/p"><img loading="lazy" src="${esc(asset(p.image))}" alt="${esc(p.name)}"></a><button class="r-heart ${favorites.includes(p.slug)?'r-liked':''}" data-favorite="${esc(p.slug)}" aria-label="${favorites.includes(p.slug)?'Remover dos':'Adicionar aos'} favoritos" aria-pressed="${favorites.includes(p.slug)}">♡</button>${p.old_price>p.price?`<span class="r-discount">${Math.round((1-p.price/p.old_price)*100)}% OFF</span>`:''}</div><div class="r-card-info">${p.reviews?`<div class="r-stars">★★★★★ <small>(${p.reviews.count||0})</small></div>`:''}<a class="r-card-name" href="/${esc(p.slug)}/p">${esc(p.name)}</a><div class="r-card-price">${p.old_price>p.price?`<del>${money(p.old_price)}</del>`:''}<strong>${money(p.price)}</strong></div><a class="r-card-cta" href="/${esc(p.slug)}/p">Escolher opções <span>→</span></a></div></article>`}
function pick(label){const n=norm(label);const re=n.includes('tote')?/tote/:n.includes('bolsa')?/bolsa/:n.includes('garrafa')?/garrafa|copo/:n.includes('capinha')?/capinha|case/:n.includes('viagem')?/mala|voyage|mochila/:n.includes('lancheira')?/termica|lancheira/:n.includes('necessaire')?/necessaire/:n.includes('pet')?/pet/:n.includes('acessorio')?/cordao|organizador|marmita|base|tampa/:null;return re?catalog.filter(p=>re.test(norm(p.name))):[...catalog.filter(p=>/clear$/.test(p.slug)).slice(0,8),...catalog]}
function homeShelves(){$$('.new-home-offers').forEach((section,i)=>{const grid=$('.new-home-offers__grid',section);if(!grid)return;const buttons=$$('.new-home-offers__tab',section);const paint=(label)=>{let pool=pick(label);if(!pool.length)pool=catalog;let items=pool.filter(p=>p.in_stock!==false).slice(0,i===2?4:8);grid.innerHTML=items.map(card).join('')};paint(i===2?'Lancheiras':'Favoritos');buttons.forEach(b=>b.addEventListener('click',()=>{buttons.forEach(x=>x.classList.toggle('new-home-offers__tab--active',x===b));paint(b.textContent)}))})}
function hero(){const slides=$$('.new-home-hero__slide'),dots=$$('.new-home-hero__dot');let index=0;if(!slides.length)return;const show=i=>{index=(i+slides.length)%slides.length;slides.forEach((s,n)=>{s.style.transform=`translateX(calc(${n-index} * (100% + var(--hero-gap))))`;s.style.opacity='1';s.style.transition='transform 320ms ease';s.style.pointerEvents=n===index?'auto':'none'});dots.forEach((d,n)=>{d.classList.toggle('new-home-hero__dot--active',n===index);d.setAttribute('aria-current',n===index?'true':'false')})};$('.new-home-hero__arrow--prev')?.addEventListener('click',()=>show(index-1));$('.new-home-hero__arrow--next')?.addEventListener('click',()=>show(index+1));dots.forEach((d,n)=>d.addEventListener('click',()=>show(n)));let timer=setInterval(()=>{if(!document.hidden)show(index+1)},7000);$('.new-home-hero')?.addEventListener('mouseenter',()=>clearInterval(timer));show(0)}
function dialog(title,body,kind=''){document.querySelector('dialog.r-dialog')?.remove();const el=document.createElement('dialog');el.className='r-dialog '+kind;el.innerHTML=`<div class="r-dialog-head"><h2 id="r-dialog-title">${title}</h2><button data-close aria-label="Fechar">×</button></div><div class="r-dialog-body">${body}</div>`;el.setAttribute('aria-labelledby','r-dialog-title');document.body.append(el);el.showModal();el.addEventListener('click',e=>{if(e.target===el||e.target.closest('[data-close]'))el.close()});el.addEventListener('close',()=>el.remove());return el}
function cartBody(drawer=false){const total=subtotal(cart);return `${cart.length?`<div class="r-cart-items">${cart.map(x=>`<article class="r-cart-item"><a href="/${esc(x.slug)}/p"><img src="${esc(asset(x.image))}" alt="${esc(x.name)}"></a><div><a href="/${esc(x.slug)}/p"><b>${esc(x.name)}</b></a><p>${esc([x.option,x.device,x.custom].filter(Boolean).join(' · '))}</p><strong>${money(x.price)}</strong><div class="r-qty"><button data-qty="-1" data-key="${esc(x.key)}" aria-label="Diminuir quantidade">−</button><span>${x.qty}</span><button data-qty="1" data-key="${esc(x.key)}" aria-label="Aumentar quantidade">+</button><button class="r-remove" data-remove="${esc(x.key)}">Remover</button></div></div></article>`).join('')}</div><div class="r-summary"><div><span>Subtotal (${cart.reduce((s,x)=>s+x.qty,0)} itens)</span><b>${money(total)}</b></div><p>Entrega calculada na etapa seguinte. Preços capturados no site de referência.</p><a class="r-primary" href="/checkout">Continuar para entrega →</a><a class="r-secondary" href="/vitrine">Continuar comprando</a></div>`:`<div class="r-empty"><span>♧</span><h3>Sua sacola está vazia</h3><p>Encontre o seu próximo favorito.</p><a class="r-primary" href="/vitrine">Explorar produtos</a></div>`}<p class="r-note">Ambiente de demonstração. Nenhuma compra real será realizada.</p>`}
function showCart(){dialog(`Minha sacola (${cart.reduce((s,x)=>s+x.qty,0)})`,cartBody(true),'r-drawer')}
function cartPage(){main.innerHTML=`<section class="r-container r-cart-page"><a href="/">Início</a><h1>Minha sacola</h1><div id="r-cart-content">${cartBody()}</div></section>`}
function refreshCart(){persistCart();if($('dialog.r-drawer')){const el=$('dialog.r-drawer');$('.r-dialog-body',el).innerHTML=cartBody();$('h2',el).textContent=`Minha sacola (${cart.reduce((s,x)=>s+x.qty,0)})`}if(path==='/cart')cartPage()}
function bindSearch(){$$('input[type="search"], input[name="q"]').forEach(input=>{input.addEventListener('input',()=>{let list=$('.r-search-results',input.parentElement);if(!list){list=document.createElement('div');list.className='r-search-results';input.parentElement.append(list)}const found=findProducts(catalog,input.value).slice(0,5);list.hidden=!input.value.trim();list.innerHTML=found.length?found.map(p=>`<a href="/${p.slug}/p"><img src="${esc(asset(p.image))}" alt=""><span>${esc(p.name)}<b>${money(p.price)}</b></span></a>`).join('')+`<a class="r-search-all" href="/search?q=${encodeURIComponent(input.value)}">Ver todos os resultados →</a>`:'<p>Nenhum produto encontrado.</p>';input.setAttribute('aria-expanded',String(!list.hidden))});input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();location.href='/search?q='+encodeURIComponent(input.value)}if(e.key==='Escape'){$('.r-search-results',input.parentElement)?.remove();input.setAttribute('aria-expanded','false')}})});$$('[aria-label="Search"]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();const input=$('input',b.parentElement);location.href='/search?q='+encodeURIComponent(input?.value||'')}));document.addEventListener('click',e=>{if(!e.target.closest('.header-search'))$$('.r-search-results').forEach(x=>x.hidden=true)})}
function catalogPage(title,items=catalog){page=1;visibleProducts=items;main.innerHTML=`<section class="r-container"><nav class="r-breadcrumb"><a href="/">Início</a> / ${esc(title)}</nav><h1>${esc(title)}</h1><nav class="r-pills">${catButton('Todos','/vitrine')}${catButton('Tote bags','/lp/totes')}${catButton('Garrafas','/lp/garrafa-termica')}${catButton('Capinhas','/capinha-para-celular/')}${catButton('Bolsas','/lp/bolsas')}${catButton('Malas','/lp/malas')}</nav><div class="r-filter-row"><span id="r-results-count">${items.length} produtos capturados</span><label>Ordenar por <select id="r-sort"><option value="featured">Destaques</option><option value="price-asc">Menor preço</option><option value="price-desc">Maior preço</option><option value="discount">Maior desconto</option><option value="name">Nome</option></select></label><label>Preço até <input id="r-max-price" type="number" min="0" placeholder="R$" aria-label="Preço máximo"></label><label><input id="r-only-stock" type="checkbox"> Em estoque</label></div><div class="r-products" id="r-products"></div><button class="r-secondary" id="r-more">Carregar mais produtos</button></section>`;const paint=()=>{let list=items;const max=Number($('#r-max-price').value);if(max>0)list=list.filter(p=>p.price<=max);if($('#r-only-stock').checked)list=list.filter(p=>p.in_stock!==false);visibleProducts=sortProducts(list,$('#r-sort').value);$('#r-results-count').textContent=visibleProducts.length+' produtos capturados';$('#r-products').innerHTML=visibleProducts.length?visibleProducts.slice(0,page*24).map(card).join(''):'<p class="r-empty">Nenhum produto encontrado com estes filtros.</p>';$('#r-more').hidden=visibleProducts.length<=page*24};['#r-sort','#r-max-price','#r-only-stock'].forEach(s=>$(s).addEventListener('change',()=>{page=1;paint()}));$('#r-more').addEventListener('click',()=>{page++;paint()});paint()}
function variantUI(p){const types=p.case_types||[];const devices=p.devices||[];return `<div class="r-options">${devices.length>1?`<label>Modelo / capacidade<select id="r-device">${devices.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label>`:''}${types.length?`<label>Cor / acabamento<select id="r-option">${types.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></label><div class="r-swatches">${types.slice(0,18).map(t=>`<button type="button" data-option="${t.id}" title="${esc(t.name)}" aria-label="Cor ${esc(t.name)}"><img src="${esc(asset(t.case_image))}" alt="${esc(t.name)}"></button>`).join('')}</div>`:''}${!/clear|organizador|base-de-silicone|tampa/.test(p.slug)&&p.customizations?.length?`<label>Personalize do seu jeito<input id="r-custom" maxlength="24" placeholder="Digite seu nome ou iniciais"></label><small class="r-note">Prévia simplificada para estudo; o editor de personalização original não está integrado.</small>`:''}<label class="r-quantity-label">Quantidade<input id="r-quantity" type="number" value="1" min="1" max="99"></label><p id="r-stock" role="status"></p></div>`}
function setupProduct(p){product=p;const mount=$('.composite-device-selector')||$('.productpage__form')||$('#r-product-options');if(mount){mount.innerHTML=variantUI(p)}$$('.product-form__skeleton,.product-form__loading,.clear-thumbnails__item--skeleton').forEach(x=>x.remove());const buy=$('#add-to-cart-box');if(buy)buy.style.display='flex';const existing=$('.product-form');if(existing)existing.addEventListener('submit',e=>{e.preventDefault();addCurrent()});else $('#r-add')?.addEventListener('click',addCurrent);if(!$('.clear-gallery__image')&&!$('#r-product-image')){const target=$('#main-image');if(target)target.innerHTML=`<img id="r-product-image" src="${esc(asset(p.image))}" alt="${esc(p.name)}">`}
 const requestedCaseDevice=Number(new URLSearchParams(location.search).get('case_device'))||p.default_case_device_id;const initialType=(p.case_types||[]).find(t=>(t.devices||[]).some(d=>d.case_device_id===requestedCaseDevice))||p.case_types?.[0];if($('#r-option')&&initialType)$('#r-option').value=initialType.id;
 const selectedId=initialType?.devices?.find(d=>d.case_device_id===requestedCaseDevice)?.device_id;if($('#r-device')&&selectedId)$('#r-device').value=selectedId;
 function update(){const type=p.case_types?.find(t=>String(t.id)===$('#r-option')?.value)||initialType;const device=p.devices?.find(d=>String(d.id)===$('#r-device')?.value)||p.devices?.[0];const pair=type?.devices?.find(x=>x.device_id===device?.id);const option=p.color_options?.find(x=>x.case_type_id===type?.id&&(!device||x.device_code===device.code));const def=p.case_types?.flatMap(t=>t.devices||[]).find(d=>d.case_device_id===p.default_case_device_id);const price=option?.price??(p.price+(pair?Number(pair.cost_price||0)-Number(def?.cost_price||0):0));let image=option?.image||p.image;if(type&&device&&image?.includes('/govinci/'))image=image.replace(/(\/govinci\/[^/]+\/)[^/]+(\/mockup)/,`$1${type.code}-${device.code}$2`);currentOption={name:type?.name||'',price:Number(price),image,in_stock:pair?pair.in_stock:p.in_stock!==false};currentDevice=device?.name||'';const pic=$('.clear-gallery__image')||$('#r-product-image');if(pic)pic.src=asset(image);const priceEl=$('.product-price__current')||$('#r-product-price');if(priceEl)priceEl.textContent=money(price);const oldPrice=Number(option?.old_price??(p.old_price+Number(price)-p.price));const previousPrice=$('.product-price__previous');if(previousPrice)previousPrice.textContent=money(oldPrice);const discount=$('.product-price__discount');if(discount)discount.textContent=oldPrice>price?Math.round((1-price/oldPrice)*100)+'% OFF':'';const stock=$('#r-stock');if(stock){stock.textContent=currentOption.in_stock?'Disponível':'Esta opção está indisponível';stock.style.color=currentOption.in_stock?'#277b5a':'#b74040'}const btn=$('#add-to-cart-button')||$('#r-add');if(btn){btn.disabled=!currentOption.in_stock;btn.setAttribute('aria-disabled',String(!currentOption.in_stock))}$$('[data-option]').forEach(x=>x.classList.toggle('r-selected',x.dataset.option===String(type?.id)))}
 $('#r-option')?.addEventListener('change',update);$('#r-device')?.addEventListener('change',update);$$('[data-option]').forEach(x=>x.addEventListener('click',()=>{$('#r-option').value=x.dataset.option;update()}));$('#r-custom')?.addEventListener('input',e=>{let overlay=$('.r-custom-preview');if(!overlay){overlay=document.createElement('span');overlay.className='r-custom-preview';($('.clear-gallery__main-stage')||$('#main-image')||$('.r-product-picture'))?.append(overlay)}overlay.textContent=e.target.value});update();
 $('.clear-gallery__image')?.addEventListener('click',()=>dialog(esc(p.name),`<img class="r-zoom" src="${esc($('.clear-gallery__image').src)}" alt="${esc(p.name)}">`));$$('.clear-thumbnails__item img').forEach(img=>img.parentElement.addEventListener('click',()=>{const target=$('.clear-gallery__image');if(target)target.src=img.src}));}
function addCurrent(){if(!product||!currentOption?.in_stock){toast('Escolha uma opção disponível.');return}const qty=Math.max(1,Math.min(99,Number($('#r-quantity')?.value)||1));cart=addItem(cart,{slug:product.slug,name:product.name,price:currentOption.price,image:currentOption.image,option:currentOption.name,device:currentDevice,custom:$('#r-custom')?.value.trim()||'',qty});persistCart();showCart()}
function genericProduct(p){main.innerHTML=`<section class="r-container"><nav class="r-breadcrumb"><a href="/">Início</a> / <a href="/vitrine">Produtos</a> / ${esc(p.name)}</nav><div class="r-product-layout"><div class="r-product-picture"><img id="r-product-image" src="${esc(asset(p.image))}" alt="${esc(p.name)}"></div><div><span class="r-promo">🔥 ESQUENTA BLACK FRIDAY 🔥</span><h1>${esc(p.name)}</h1><div class="r-product-prices"><del>${money(p.old_price)}</del><strong id="r-product-price">${money(p.price)}</strong></div><div id="r-product-options"></div><button id="r-add" class="r-primary">Adicionar ao Carrinho</button></div></div>${p.description?`<details class="r-description" open><summary>Descrição e especificações</summary><div>${p.description.replace(/\r?\n/g,'<br>')}</div></details>`:'<p class="r-note">Descrição detalhada não capturada nesta versão. Consulte a cobertura da cópia.</p>'}</section>`;setupProduct(p)}
function bindAccordions(){$$('.product-faq__trigger').forEach(b=>b.addEventListener('click',()=>{const answer=b.nextElementSibling;const open=b.getAttribute('aria-expanded')==='true';b.setAttribute('aria-expanded',String(!open));if(answer)answer.style.display=open?'none':'block';const icon=$('.product-faq__icon',b);if(icon)icon.textContent=open?'+':'−'}));$$('.clear-product-info-sections__tab-title').forEach(b=>b.addEventListener('click',()=>{const row=b.parentElement;row.classList.toggle('r-tab-open');b.setAttribute('aria-expanded',String(row.classList.contains('r-tab-open')))}));$$('.new-home-reviews__more').forEach(b=>b.addEventListener('click',()=>{const quote=$('.new-home-reviews__quote',b.parentElement);quote.style.webkitLineClamp=b.getAttribute('aria-expanded')==='true'?'4':'unset';b.setAttribute('aria-expanded',String(b.getAttribute('aria-expanded')!=='true'));b.textContent=b.getAttribute('aria-expanded')==='true'?'ver menos':'ver mais'}));[['.new-home-reviews','.new-home-reviews__cards'],['.new-home-universes','.new-home-universes__track']].forEach(([s,t])=>{const el=$(s);if(!el)return;$$('button',el).filter(b=>/anteriores|próxim|anterior/i.test(b.getAttribute('aria-label')||'')).forEach(b=>b.addEventListener('click',()=>{const track=$(t)||$('[class*="__cards"], [class*="__track"]',el);track?.scrollBy({left:/anter/i.test(b.getAttribute('aria-label'))?-400:400,behavior:'smooth'})}))})}
function checkout(){if(!cart.length){cartPage();return}main.innerHTML=`<section class="r-container"><a href="/cart">← Voltar à sacola</a><h1>Entrega e pagamento</h1><p class="r-banner-note">Simulação de compra para revisão. Não informe dados reais de pagamento.</p><div class="r-checkout"><form id="r-checkout-form"><h2>1. Entrega</h2><label>CEP<input name="cep" id="r-cep" inputmode="numeric" placeholder="00000-000" pattern="[0-9]{5}-?[0-9]{3}" required></label><button class="r-secondary" type="button" id="r-calculate">Calcular entrega de demonstração</button><p id="r-delivery" role="status"></p><h2>2. Pagamento</h2><label><input type="radio" name="payment" value="Pix" checked> Pix</label><label><input type="radio" name="payment" value="Cartão de crédito"> Cartão de crédito</label><p class="r-note">Métodos exibidos para revisar o fluxo. Não há cobrança, processamento de cartão ou geração de Pix.</p><button class="r-primary" type="submit">Concluir pedido de demonstração</button></form><aside class="r-summary"><h2>Resumo do pedido</h2>${cart.map(x=>`<div><span>${x.qty} × ${esc(x.name)}</span><b>${money(x.qty*x.price)}</b></div>`).join('')}<hr><div><b>Subtotal</b><strong>${money(subtotal(cart))}</strong></div><div><span>Frete de demonstração</span><b id="r-shipping-price">A calcular</b></div><div><b>Total</b><strong id="r-total">${money(subtotal(cart))}</strong></div><label>Cupom<input id="r-coupon" placeholder="Digite o cupom"></label><button class="r-secondary" type="button" id="r-apply-coupon">Aplicar</button><p id="r-coupon-result" role="status"></p></aside></div></section>`;let deliverySet=false;$('#r-calculate').addEventListener('click',()=>{const cep=$('#r-cep');if(!cep.reportValidity())return;deliverySet=true;$('#r-delivery').textContent='Entrega simulada: 5 a 8 dias úteis · R$ 14,90. Prazo e frete fictícios para teste.';$('#r-shipping-price').textContent=money(14.9);$('#r-total').textContent=money(subtotal(cart)+14.9)});$('#r-apply-coupon').addEventListener('click',()=>{$('#r-coupon-result').textContent='Cupons do site original dependem da integração de promoções. Nenhum desconto foi aplicado.'});$('#r-checkout-form').addEventListener('submit',e=>{e.preventDefault();if(!deliverySet){toast('Calcule a entrega de demonstração antes de continuar.');return}const order={id:'DEMO-'+Date.now().toString(36).toUpperCase(),items:cart,total:subtotal(cart)+14.9,createdAt:new Date().toISOString()};save('order',order);cart=[];persistCart();main.innerHTML=`<section class="r-container r-empty"><span>✓</span><h1>Pedido de demonstração concluído</h1><p>${order.id}</p><p>Nenhum pagamento foi realizado e nenhum pedido foi enviado à Gocase.</p><a class="r-primary" href="/find-order">Consultar demonstração</a><a class="r-secondary" href="/">Voltar ao início</a></section>`})}
function information(){main.innerHTML=`<section class="r-container r-document"><h1>Sobre esta cópia</h1><p>Ambiente privado de estudo do site público Gocase, capturado em 14/11/2026. A marca, fotografias, páginas e dados comerciais foram mantidos como referência visual para análise de melhorias.</p><h2>O que foi preservado</h2><p>HTML e estilos das páginas capturadas, banners responsivos, menus, descrições disponíveis, fotos e preços da data de captura. <a href="/data/coverage.json">Ver inventário técnico</a>.</p><h2>Interações de demonstração</h2><p>Busca no catálogo capturado, filtros, favoritos, seleção de cores e modelos, carrinho persistente neste navegador e checkout simulado. A prévia de personalização é simplificada.</p><h2>Limites da cópia</h2><p>Não é uma cópia integral do sistema de produção. Estoque e preços não são sincronizados. Catálogo completo, recomendações personalizadas e todas as variantes não foram capturados. Algumas rotas utilizam uma vitrine local de apoio.</p><p>Login, cadastro, rastreamento real, promoções, cálculo de frete, personalização 3D, Pix e cartão dependem dos serviços privados do site original e não estão integrados. Os formulários não enviam dados à Gocase.</p><h2>Privacidade</h2><p>Carrinho, favoritos e pedido de demonstração são guardados apenas no navegador. Senhas, cartão e informações de pagamento não são solicitados nem armazenados pela implementação.</p><button class="r-secondary" id="r-clear-data">Limpar dados da demonstração</button></section>`;$('#r-clear-data').addEventListener('click',()=>{['cart','favorites','order','profile'].forEach(k=>{try{localStorage.removeItem('gocase-study:'+k)}catch{}});cart=[];favorites=[];updateCount();toast('Dados locais apagados.')})}
function bindForms(){if(product)return;$$('form').forEach(form=>{if(form.id.startsWith('r-'))return;form.addEventListener('submit',e=>{e.preventDefault();if(path==='/find-order'){const order=read('order',null);const input=$('input:not([type=hidden])',form);if(order&&(!input?.value||input.value===order.id)){dialog('Pedido de demonstração',`<p><b>${esc(order.id)}</b></p><p>Etapa: simulação concluída.</p><p>Nenhum pedido real foi enviado ou despachado.</p>`)}else toast('Rastreamento real depende da integração com pedidos. Use um pedido DEMO criado nesta cópia.')}else if(/login|signup/.test(path)){toast('Tela de referência: autenticação e cadastro reais não estão integrados. Nenhum dado foi enviado.');$$('input[type=password]',form).forEach(x=>x.value='')}else toast('Formulário de demonstração. Nenhum dado foi enviado.')})});if(path==='/find-order'){const order=read('order',null);const host=$('form');if(host){const note=document.createElement('p');note.className='r-banner-note';note.textContent=order?`Pedido para testar: ${order.id}`:'Rastreamento de demonstração. Crie um pedido no checkout para testar.';host.prepend(note)}}if(/login|signup/.test(path)){$$('input[type=password]').forEach(input=>{input.disabled=true;input.placeholder='Autenticação não integrada'});const host=$('form');if(host){const n=document.createElement('p');n.className='r-banner-note';n.textContent='Cópia para revisão. Login e cadastro reais não estão integrados; não informe credenciais.';host.prepend(n)}}}
function bindNavigation(){$$('.new-home-header__burger').forEach(b=>b.addEventListener('click',()=>{const nav=$('.new-home-header__nav-inner');dialog('Explore a Gocase',`<nav class="r-mobile-nav">${nav?nav.innerHTML:''}<a href="/wishlist">Meus favoritos</a><a href="/login">Entrar</a><a href="/find-order">Rastrear pedido</a></nav>`,'r-drawer r-menu')}));$$('.header-account-menu__trigger').forEach(t=>{const host=t.closest('.header-account-menu'),panel=$('.header-account-menu__panel',host);if(!panel)return;host.addEventListener('mouseenter',()=>{panel.style.display='block';t.setAttribute('aria-expanded','true')});host.addEventListener('mouseleave',()=>{panel.style.display='none';t.setAttribute('aria-expanded','false')})});$$('.new-home-header__cart,a[href="/cart"]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();showCart()}));}
document.addEventListener('click',e=>{const fav=e.target.closest('[data-favorite]');if(fav){const slug=fav.dataset.favorite;favorites=favorites.includes(slug)?favorites.filter(x=>x!==slug):[...favorites,slug];save('favorites',favorites);fav.classList.toggle('r-liked',favorites.includes(slug));fav.setAttribute('aria-pressed',String(favorites.includes(slug)));toast(favorites.includes(slug)?'Adicionado aos favoritos':'Removido dos favoritos');if(path==='/wishlist')catalogPage('Meus favoritos',catalog.filter(p=>favorites.includes(p.slug)))}const qty=e.target.closest('[data-qty]');if(qty){cart=cart.map(x=>x.key===qty.dataset.key?{...x,qty:Math.max(1,Math.min(99,x.qty+Number(qty.dataset.qty)))}:x);refreshCart()}const remove=e.target.closest('[data-remove]');if(remove){cart=cart.filter(x=>x.key!==remove.dataset.remove);refreshCart()}});
async function boot(){try{[catalog,assetMap]=await Promise.all([fetch('/data/catalog.json').then(r=>r.json()),fetch('/data/assets.json').then(r=>r.ok?r.json():{}).catch(()=>({}))]);updateCount();bindNavigation();bindSearch();hero();homeShelves();bindAccordions();
 if(/\/p(?:\/\d+)?$/.test(path)){const slug=path.split('/').filter(Boolean)[0];try{const r=await fetch('/data/products/'+encodeURIComponent(slug)+'.json');if(r.ok){const p=await r.json();if(main)genericProduct(p);else if($('astro-island[component-url*="BuyBox"]'))setupAstroProduct(p);else setupProduct(p)}else if(main)catalogPage('Produto não capturado',[])}catch{toast('Não foi possível carregar este produto.')}}
 else if(main){if(path==='/cart')cartPage();else if(path==='/checkout')checkout();else if(path==='/wishlist')catalogPage('Meus favoritos',catalog.filter(p=>favorites.includes(p.slug)));else if(path==='/sobre-a-copia')information();else if(path==='/account')main.innerHTML='<section class="r-container"><h1>Minha conta</h1><p>Área de demonstração. Autenticação, pedidos e dados da conta original dependem de integração.</p><a class="r-primary" href="/find-order">Consultar pedido de demonstração</a></section>';else if(path==='/central-de-ajuda')main.innerHTML='<section class="r-container r-document"><h1>Central de ajuda</h1><details open><summary>Como acompanhar meu pedido?</summary><p>Você pode revisar o fluxo de rastreamento em <a href="/find-order">Rastrear pedido</a>. Nesta cópia são aceitos apenas pedidos de demonstração.</p></details><details><summary>Trocas e garantia</summary><p>As condições capturadas estão nas descrições e perguntas frequentes dos respectivos produtos.</p></details><details><summary>Esta loja realiza compras?</summary><p>Este ambiente é uma cópia privada para estudo. O checkout é simulado.</p></details></section>';else if(path==='/search'){const q=new URLSearchParams(location.search).get('q')||'';catalogPage(q?`Resultados para “${q}”`:'Todos os produtos',findProducts(catalog,q))}else{const groups=await fetch('/data/groups.json').then(r=>r.json());const slugs=groups[path];const title=path.includes('vitrine')?'Todos os produtos':path.split('/').filter(Boolean).at(-1)?.replace(/-/g,' ')||'Produtos';let items=slugs?catalog.filter(p=>slugs.includes(p.slug)):findProducts(catalog,title);if(!items.length)items=pick(title);catalogPage(title.charAt(0).toUpperCase()+title.slice(1),items)}}
 bindForms();$$('.plp-showcase__load-more').forEach(button=>button.addEventListener('click',()=>{location.href='/search?q='+encodeURIComponent(path.includes('totes')?'tote':path.includes('garrafa')?'garrafa':path.includes('malas')?'mala':path.includes('bolsas')?'bolsa':'')}));
 }catch(error){console.error('Falha ao iniciar a cópia',error);toast('Falha ao carregar os dados locais. Atualize a página.');if(main)main.innerHTML='<section class="r-container"><h1>Não foi possível carregar a página</h1><a href="/">Voltar ao início</a></section>'}}
boot();
// Static capture keeps the original card markup; reconnect its color controls locally.
document.addEventListener('click',async e=>{const swatch=e.target.closest('.product-card__swatch');if(!swatch)return;const host=swatch.closest('.product-card'),link=$('.product-card__media-link',host);const slug=link?.getAttribute('href')?.split('/').filter(Boolean)[0];if(!slug)return;try{const p=await fetch('/data/products/'+encodeURIComponent(slug)+'.json').then(r=>r.json());const material=(swatch.getAttribute('aria-label')||'').split(',')[0];const option=p.color_options?.find(x=>x.material===material);const img=$('.product-card__image',host);if(img){let url=option?.image||p.image?.replace(/(\/govinci\/[^/]+\/)[^/]+(\/mockup)/,`$1${material}$2`);if(url)img.src=asset(url)}if(option){const price=$('.product-card__price-now',host);if(price)price.textContent=money(option.price);link.href='/'+slug+'/p?case_device='+option.case_device_id}$$('.product-card__swatch',host).forEach(x=>{x.classList.toggle('product-card__swatch--selected',x===swatch);x.setAttribute('aria-pressed',String(x===swatch))})}catch{toast('Esta opção não foi capturada. Abra o produto para escolher.')}});
function setupAstroProduct(p){product=p;const box=$('astro-island[component-url*="BuyBox"]');const update=()=>{const selected=$('input[type="radio"]:checked',box);const id=Number(selected?.value)||p.default_case_device_id;const t=p.case_types.find(t=>t.devices.some(d=>d.case_device_id===id));const option=p.color_options.find(x=>x.case_device_id===id);const d=t?.devices.find(x=>x.case_device_id===id);currentOption={name:t?.name||'',price:option?.price||p.price,image:option?.image||p.image,in_stock:d?.in_stock!==false};currentDevice=p.devices[0]?.name||'';const price=$('[data-testid="price"]',box);if(price)price.textContent=money(currentOption.price);const old=$('[data-testid="old-price"]',box);if(old)old.textContent=money(option?.old_price||p.old_price);$$('[data-scope="radio-group"][data-part="item"]',box).forEach(label=>{const checked=!!$('input:checked',label);label.dataset.state=checked?'checked':'unchecked';$$('[data-state]',label).forEach(el=>el.dataset.state=label.dataset.state)});const image=$('[data-gallery-track] img');if(image){image.removeAttribute('srcset');image.src=asset(currentOption.image)}const button=$('[data-testid="add-to-cart"]',box);if(button)button.disabled=!currentOption.in_stock};$$('input[type="radio"]',box).forEach(x=>x.addEventListener('change',update));$('[data-testid="add-to-cart"]',box)?.addEventListener('click',addCurrent);const fav=$('[data-testid="favourite"]',box);if(fav)fav.dataset.favorite=p.slug;$$('[data-gallery-thumb]').forEach(t=>t.addEventListener('click',()=>{const index=Number(t.dataset.galleryThumb||t.dataset.galleryIndex)||0;const track=$('[data-gallery-track]');track?.scrollTo({left:track.clientWidth*index,behavior:'smooth'})}));$$('form[role="search"]').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();location.href='/search?q='+encodeURIComponent($('input',f)?.value||'')}));update()}
